        6: {"exp":{"en":"CPU stands for Central Processing Unit. It fetches each instruction, decodes it, and then carries it out.","hi":"CPU का पूरा नाम सेंट्रल प्रोसेसिंग यूनिट है। यह प्रत्येक निर्देश प्राप्त करता है, उसका अर्थ समझता है और उसे पूरा करता है।"},"o":[{"en":"Central Printing Unit — prepares print output","hi":"सेंट्रल प्रिंटिंग यूनिट — छपाई के लिए परिणाम तैयार करती है"},{"en":"Central Processing Unit — executes instructions","hi":"सेंट्रल प्रोसेसिंग यूनिट — निर्देश चलाती है"},{"en":"Control Processing Unit — stores user files","hi":"कंट्रोल प्रोसेसिंग यूनिट — उपयोगकर्ता की फ़ाइलें सहेजती है"},{"en":"Central Program Unit — displays graphics","hi":"सेंट्रल प्रोग्राम यूनिट — ग्राफिक्स दिखाती है"}],"a":{"en":"Central Processing Unit — executes instructions","hi":"सेंट्रल प्रोसेसिंग यूनिट — निर्देश चलाती है"}},
